const grid = window.__grid;
function run(rule, N, synthetic) {
  let state = null, streak = 0, streakState = null, flips = {victron: 0, meter_2: 0}, firstConfirm = null, m2Minutes = 0, lastT = null;
  for (const [t, a, v, g] of grid) {
    if (state === 'meter_2' && lastT !== null) m2Minutes += (t - lastT) / 60000;
    lastT = t;
    if (a == null || v == null || g == null) { streak = 0; streakState = null; continue; }
    const vv = synthetic ? v - a : v;
    const r = vv - g;
    const d = rule(a, r);
    if (d == null) continue;
    if (d === state) { streak = 0; streakState = null; continue; }
    if (d !== streakState) { streakState = d; streak = 0; }
    streak++;
    if (streak >= N) { if (state !== null || true) flips[d]++; if (firstConfirm === null) firstConfirm = {t: new Date(t).toISOString(), d}; state = d; streak = 0; streakState = null; }
  }
  return {flips, m2_hours: Math.round(m2Minutes/6)/10, first: firstConfirm && firstConfirm.d};
}
const rules = {
  'abs a-100 (obecna)': (a, r) => a < 300 ? null : (r >= a - 100 ? 'victron' : 'meter_2'),
  'ratio r<0.5a': (a, r) => a < 300 ? null : (r < 0.5 * a ? 'meter_2' : 'victron'),
  'pasmo victron>=0.75a, meter_2<0.35a': (a, r) => a < 300 ? null : (r >= 0.75 * a ? 'victron' : (r < 0.35 * a ? 'meter_2' : null)),
};
