const hass = document.querySelector('home-assistant').hass;
const PPE1 = 'tauron_importer:3685152_60114680_3685152_consumption', APT = 'sensor.tongou_m3_energy';
const months = ['2026-07','2026-08','2026-09','2026-10'];
const out = [];
for (const m of months) {
  const [y, mo] = m.split('-').map(Number);
  const days = m === '2026-10' ? 16 : new Date(y, mo, 0).getDate();
  const t0 = new Date(`${m}-01T00:00:00`); const t1 = new Date(y, mo - 1, days + 1);
  const st = await hass.callWS({type:'recorder/statistics_during_period', start_time: t0.toISOString(), end_time: t1.toISOString(), statistic_ids:[PPE1, APT], period:'hour', types:['change']});
  const ix = id => { const mm = new Map(); for (const r of (st[id]||[])) mm.set(typeof r.start==='number'?r.start:Date.parse(r.start), r.change); return mm; };
  const p1 = ix(PPE1), ap = ix(APT);
  let hoursOver = 0, movableKwh = 0, saving = 0, savingAll = 0, aptMissing = 0;
  for (let d = 1; d <= days; d++) {
    const r = await hass.callWS({type:'powerpilot/prices', date:`${m}-${String(d).padStart(2,'0')}`});
    for (const h of (r.hours||[])) {
      if (h.tge_kwh == null) continue;
      const p = (h.tge_kwh + (h.markup_kwh||0)) * (1 + (h.vat_rate ?? 0.23));
      if (p <= 0.61) continue;
      const t = Date.parse(h.start); const imp = p1.get(t); const a = ap.get(t);
      if (imp == null) continue;
      hoursOver++;
      savingAll += imp * (p - 0.61);
      if (a == null) { aptMissing++; continue; }
      const mov = Math.max(0, Math.min(a, imp));
      movableKwh += mov; saving += mov * (p - 0.61);
    }
  }
  out.push(`${m}: hours>0.61 with data=${hoursOver}, apartment kWh not covered by battery=${movableKwh.toFixed(1)}, saving if all moved=${saving.toFixed(2)} zł (all PPE1 import: ${savingAll.toFixed(2)} zł), apt missing=${aptMissing}`);
}
out

