const st = await hass.callWS({type:'recorder/statistics_during_period', start_time: t0.toISOString(), end_time: t1.toISOString(), statistic_ids:[PPE1, APT, BIN], period:'hour', types:['change']});
const ix = id => { const m = new Map(); for (const r of (st[id]||[])) m.set(typeof r.start==='number'?r.start:Date.parse(r.start), r.change); return m; };
const p1 = ix(PPE1), ap = ix(APT), bi = ix(BIN);
let aptExp = 0, aptExpCost = 0, uncovered = 0, uncSaving = 0, chKwh = 0, chCost = 0, aptAll = 0;
for (let d = 1; d <= 16; d++) {
  const r = await hass.callWS({type:'powerpilot/prices', date:`2026-10-${String(d).padStart(2,'0')}`});
  for (const h of (r.hours||[])) {
    if (h.tge_kwh == null) continue;
