const hass = document.querySelector('home-assistant').hass;
const plan = await hass.callWS({type: 'powerpilot/plan'});
const L = 0.61, TH = 2.0, STAY = 2;
const H = plan.hours.map((h,i)=>{ const t=h.trace||{}; const f=plan.forecast[i]||{}; return {start:h.start, hr:+h.start.slice(11,13), A:t.apartment_kwh ?? f.apartment_kwh ?? 0, p:(t.cap_price ?? t.energy_price), d:t.distribution||0, conf:!!f.price_confirmed, sup:h.supply}; });
const n = H.length;
// value of an hour on PPE 2 instead of PPE 1 from the grid (distribution is the same tariff on both meters)
const v = H.map(x=>x.A*(x.p-L));
// DP over (t, state, hours since last switch capped at STAY); slot 0 fixed on victron
const NEG=-1e9; let dp={}; const key=(s,k)=>s+'_'+k;
dp[key(0,STAY)]={val:0, path:[0]};
for (let t=1;t<n;t++){ const nd={}; const allowed = !(H[t].hr>=0 && H[t].hr<9);
  for (const [kk,st] of Object.entries(dp)){ const [s,k]=kk.split('_').map(Number);
    const opts=[[s, Math.min(STAY,k+1), 0]];
    if (allowed && k>=STAY) opts.push([1-s, 1, (1-s)===1 ? -TH : 0]);
    for (const [ns,nk,c] of opts){ const val=st.val+c+(ns===1?v[t]:0); const kk2=key(ns,nk); if(!nd[kk2]||nd[kk2].val<val) nd[kk2]={val, path:st.path.concat(ns)}; } }
  dp=nd; }
const best=Object.values(dp).reduce((a,b)=>a.val>b.val?a:b);
// cycles from the best path
const cycles=[]; let cur=null;
best.path.forEach((s,t)=>{ if(s===1&&!cur){cur={from:H[t].start.slice(5,16),t0:t,A:0,val:0,mkt:0,h:0};} if(s===1){cur.A+=H[t].A;cur.val+=v[t];cur.mkt+=H[t].A*H[t].p;cur.h++;} if(s===0&&cur){cur.to=H[t].start.slice(5,16);cycles.push(cur);cur=null;} });
if(cur){cur.to='koniec horyzontu '+H[n-1].start.slice(5,16);cycles.push(cur);}
// same 70 h cycle as the live recommendation
let c70={A:0,val:0,mkt:0,h:0,neg:0}; H.forEach((x,t)=>{ if(x.sup==='meter_2'){c70.A+=x.A;c70.val+=v[t];c70.mkt+=x.A*x.p;c70.h++; if(v[t]<0)c70.neg+=v[t];} });
// whole week on PPE 2 from 18:00
let wk={A:0,val:0,mkt:0}; H.forEach((x,t)=>{ if(t>=1){wk.A+=x.A;wk.val+=v[t];wk.mkt+=x.A*x.p;} });
const below = H.filter((x,t)=>t>=1&&x.p<L).map(x=>x.start.slice(5,16)+' '+x.p.toFixed(3));
const confirmedUntil = H.filter(x=>x.conf).map(x=>x.start).pop();
({n, confirmedUntil, cycles: cycles.map(c=>({od:c.from, do:c.to, h:c.h, kWh:+c.A.toFixed(2), rynek:+c.mkt.toFixed(2), ppe2:+(L*c.A).toFixed(2), oszczednosc:+c.val.toFixed(2)})), c70:{h:c70.h,kWh:+c70.A.toFixed(2),rynek:+c70.mkt.toFixed(2),ppe2:+(L*c70.A).toFixed(2),oszczednosc:+c70.val.toFixed(2)}, tydzien:{kWh:+wk.A.toFixed(2), rynek:+wk.mkt.toFixed(2), ppe2:+(L*wk.A).toFixed(2), oszczednosc:+wk.val.toFixed(2)}, godziny_ponizej_limitu: below})

