const plan = await hass.callWS({type: 'powerpilot/plan'});
const st = await hass.callWS({type: 'powerpilot/status'});
const sup = st.supply || {};
const ents = Object.values(hass.states).filter(s => s.entity_id.includes('powerpilot') && /zasilanie|apartment|supply|przelacz|licznik|plan/i.test(s.entity_id)).map(s => [s.entity_id, s.state, s.last_updated, s.last_changed]);
const log = await hass.callWS({type: 'powerpilot/log'}).catch(e => ({err: String(e)}));
const entries = (log.entries || log || []);
const recent = Array.isArray(entries) ? entries.filter(e => JSON.stringify(e).includes('T17:5') || JSON.stringify(e).includes('T18:0') || JSON.stringify(e).includes('T16:0')).slice(-8) : Object.keys(log);
({created: plan.created_at, h0: plan.hours[0].start, h0supply: plan.hours[0].supply, h1: plan.hours[1] && [plan.hours[1].start, plan.hours[1].supply], state: sup.state, since: sup.since, transitions: (sup.transitions||[]).slice(-3), resolves: sup.plan_resolves, resolve_s: sup.plan_resolve_seconds, cycles: sup.plan_cycles, rec: sup.recommendation && {recommended: sup.recommendation.recommended, actual: sup.recommendation.actual, switch_required: sup.recommendation.switch_required, msg: sup.recommendation.notice_message}, ents, recent})

