const ids = ['sensor.tongou_m3_power','sensor.ess_multiplus_ii_output_power_l1','sensor.garage_server_socket_power'];
const start = new Date('2026-10-03T12:00:00Z'); const end = new Date();
const r = await hass.callWS({type:'history/history_during_period', start_time: start.toISOString(), end_time: end.toISOString(), entity_ids: ids, minimal_response: true, no_attributes: true, significant_changes_only: false});
const series = ids.map(id => (r[id]||[]).map(x => { const t = x.lu !== undefined ? x.lu*1000 : Date.parse(x.last_updated || x.last_changed); const v = parseFloat(x.s ?? x.state); return [t, Number.isFinite(v) ? v : null]; }));
window.__pp_series = series; window.__pp_range = [start.getTime(), end.getTime()];
({counts: series.map(s=>s.length), first: series.map(s=>s[0] && new Date(s[0][0]).toISOString()), last: series.map(s=>s[s.length-1] && new Date(s[s.length-1][0]).toISOString())})

