const series = window.__pp_series; const [t0, t1] = window.__pp_range;
const SWITCH = Date.parse('2026-10-17T15:58:50Z');
function run(minW, share, N, phaseS) {
  const idx = [0,0,0]; const cur = [null,null,null];
  let state = 'victron', streakState = null, streakStart = null, streak = 0;
  const trans = [];
  for (let t = t0 + phaseS*1000; t <= t1; t += 30000) {
    for (let k=0;k<3;k++){ const s=series[k]; while (idx[k] < s.length && s[idx[k]][0] <= t) { cur[k] = s[idx[k]][1]; idx[k]++; } }
    const a = cur[0], v = cur[1], o = cur[2];
    if (a===null || v===null || o===null) { streakState=null; streakStart=null; streak=0; continue; }
    const net = v - o;
    let d = null; if (a >= minW) d = net < share*a ? 'meter_2' : 'victron';
    if (d === null) continue;
    if (d === state) { streakState=null; streakStart=null; streak=0; continue; }
    if (d !== streakState) { streakState=d; streakStart=t; streak=0; }
    streak++;
    if (streak >= N) { trans.push({state:d, at:streakStart, confirmed:t}); state=d; streakState=null; streakStart=null; streak=0; }
  }
  const before = trans.filter(x => x.at < SWITCH - 60000);
  const falseEp = before.filter(x => x.state==='meter_2').length;
  const det = trans.find(x => x.state==='meter_2' && x.at >= SWITCH - 60000);
  const fmt = ms => new Date(ms).toLocaleTimeString('pl-PL',{timeZone:'Europe/Warsaw'});
  return {false_meter_2: falseEp, transitions_before: before.length, detected: det ? `${fmt(det.at)} (potw. ${fmt(det.confirmed)})` : 'jeszcze nie', streak_now: streakState==='meter_2'?streak:0, state_now: state};
}
const out = {};
for (const minW of [300, 250, 200, 150, 120, 100]) for (const ph of [0, 10, 20]) out[`${minW}W ph${ph}`] = run(minW, 0.5, 10, ph);
out

