const series = window.__pp_series; const [t0] = window.__pp_range;
const SWITCH = Date.parse('2026-10-17T15:58:50Z');
const fmt = ms => new Date(ms).toLocaleString('pl-PL',{timeZone:'Europe/Warsaw'});
function scan(minW, share, phaseS) {
  const idx=[0,0,0], cur=[null,null,null]; let ticks=0, decisive=0, maxStreak=0, streak=0, streakStart=null, worst=null, nightTicks=0, nightDec=0;
  const firstFalse=[];
  for (let t=t0+phaseS*1000; t < SWITCH; t+=30000) {
    for (let k=0;k<3;k++){ const s=series[k]; while(idx[k]<s.length && s[idx[k]][0]<=t){cur[k]=s[idx[k]][1]; idx[k]++;} }
    const [a,v,o]=cur; ticks++;
    const hr = +new Date(t).toLocaleString('en-GB',{timeZone:'Europe/Warsaw', hour:'2-digit', hour12:false});
    const night = hr < 9; if (night) nightTicks++;
    if (a===null||v===null||o===null){ streak=0; continue; }
    if (a < minW) continue;
    decisive++; if (night) nightDec++;
    if (v-o < share*a) { if (streak===0) streakStart=t; streak++; if (streak>maxStreak){maxStreak=streak; worst={at:fmt(streakStart), a, net:v-o};} }
    else streak=0;
  }
  return {decisive_pct: +(100*decisive/ticks).toFixed(1), night_decisive_pct: +(100*nightDec/nightTicks).toFixed(1), max_false_streak: maxStreak, worst};
}
const out={};
for (const w of [300,200,150,120]) for (const ph of [0,10,20]) out[`${w}W ph${ph}`]=scan(w,0.5,ph);
out

