const entries = await hass.callWS({type: 'config_entries/get', domain: 'powerpilot'});
const entry = entries[0];
let step = await hass.callApi('POST', 'config/config_entries/options/flow', {handler: entry.entry_id, show_advanced_options: false});
const menu = {type: step.type, step_id: step.step_id, menu: step.menu_options};
step = await hass.callApi('POST', `config/config_entries/options/flow/${step.flow_id}`, {next_step_id: 'supply'});
window.__pp_flow = step.flow_id;
({entry: [entry.entry_id, entry.state], menu, form: {type: step.type, step_id: step.step_id, schema: step.data_schema.map(f => ({name: f.name, default: f.default, desc: f.description, required: f.required, sel: f.selector && Object.keys(f.selector)[0]}))}})

