interface SeriesHour {
  start: string;
  is_past: boolean;
  buy_price: number | null;
  distribution_price_kwh: number | null;
  total_price_kwh: number | null;
  price_confirmed: boolean;
  price_type: PriceType | null;
  consumption_real: number | null;
  consumption_forecast: number | null;
  base_consumption_forecast: number | null;
  soc: number | null;
  ev_soc: number | null;
  battery_soc_start: number | null;
  inverter_mode: string | null;
  partial?: boolean;
  partial_until?: string;
  realized: TipSide | null;
  forecast: TipSide | null;
  /** Inverter mode the hour's own plan chose as it began (vintage index 0). */
  planned_mode?: string | null;
  /** Current hour only: the full-hour plan the hour STARTED with — the
   *  baseline for plan-vs-realization (the live decision may already be a
   *  mid-hour re-plan covering only the remainder). */
  hour_plan?: HourPlan | null;
  // When the forecast side was made (ISO), so the tooltip can show the vintage.
  forecast_origin?: string | null;
  /** Re-plans that happened AFTER this hour began (oldest first). The forecast
   *  side is frozen at the hour's start, so without these a mid-hour change of
   *  mind — the EV cable going in, a calendar edit — is invisible and reads as
   *  the plan simply having been wrong. */
  revisions?: PlanRevision[] | null;
  /** Re-plans dropped at the per-hour storage cap (never silently). */
  revisions_dropped?: number | null;
  /** Realized EV charging that neither the hour's plan nor any of its revisions
   *  asked for — i.e. the charger ran off-plan. */
  ev_off_plan?: boolean | null;
  battery_charge_kwh: number | null;
  battery_discharge_kwh: number | null;
