function deepFind(root, pred, depth = 0) {
  if (depth > 12 || !root) return null;
  const els = root.querySelectorAll ? root.querySelectorAll('*') : [];
  for (const el of els) {
    if (pred(el)) return el;
    if (el.shadowRoot) { const r = deepFind(el.shadowRoot, pred, depth + 1); if (r) return r; }
  }
  return null;
}
const panel = deepFind(document, el => el.tagName && el.tagName.toLowerCase() === 'powerpilot-panel');
const chartHost = panel && deepFind(panel.shadowRoot, el => el.classList && el.classList.contains('apexcharts-canvas'));
if (chartHost) chartHost.scrollIntoView({block: 'start'});
const legend = panel && Array.from(panel.shadowRoot.querySelectorAll('.apexcharts-legend-text')).map(e => e.textContent);
({found: !!panel, chart: !!chartHost, legend})

