const hass = document.querySelector('home-assistant').hass;
const repos = await hass.callWS({type: 'hacs/repositories/list'});
const repo = repos.find(r => /powerpilot/i.test(r.full_name));
await hass.callWS({type: 'hacs/repository/refresh', repository: repo.id});
let u;
for (let i = 0; i < 10; i++) {
  await new Promise(r => setTimeout(r, 2000));
  u = (await hass.callWS({type: 'get_states'})).find(s => s.entity_id === 'update.powerpilot_update');
  if (u.attributes.latest_version === 'v2.8.0') break;
}
if (u.attributes.latest_version === 'v2.8.0') {
  await hass.callService('update', 'install', {entity_id: 'update.powerpilot_update'});
  for (let i = 0; i < 30; i++) {
    await new Promise(r => setTimeout(r, 2000));
    u = (await hass.callWS({type: 'get_states'})).find(s => s.entity_id === 'update.powerpilot_update');
    if (!u.attributes.in_progress && u.attributes.installed_version === 'v2.8.0') break;
  }
}
const res = [u.state, u.attributes.installed_version, u.attributes.latest_version, u.attributes.in_progress];
if (u.attributes.installed_version === 'v2.8.0') hass.callService('homeassistant', 'restart', {}).catch(() => {});
res

