      display: flex;
      flex-direction: column;
      gap: 5px;
    }
    .card.computed {
      border-style: dashed;
      border-left-style: solid;
      background: color-mix(in srgb, var(--accent) 7%, var(--card-background-color, #fff));
    }
    .card.dim {
      opacity: 0.55;
    }
    .head {
      display: flex;
      gap: 8px;
      align-items: flex-start;
    }
    .icon {
      font-size: 15px;
      line-height: 18px;
