      color: var(--secondary-text-color);
      font-size: 11px;
      line-height: 14px;
    }
    .row {
      display: grid;
      grid-template-columns: 1fr auto;
      column-gap: 8px;
      align-items: baseline;
    }
    .label {
      color: var(--secondary-text-color);
    }
    .value {
      font-variant-numeric: tabular-nums;
      text-align: right;
    }
    .value.strong {
      font-weight: 600;
    }
    .eid {
      grid-column: 1 / -1;
      font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
      font-size: 10px;
      color: var(--secondary-text-color);
      opacity: 0.8;
      overflow-wrap: anywhere;
    }
