    }
    .term {
      display: inline-flex;
      flex-direction: column;
      align-items: center;
      padding: 2px 6px;
      border-radius: 6px;
      background: color-mix(in srgb, var(--accent) 10%, transparent);
      line-height: 1.15;
    }
    .term.struck .tv {
      text-decoration: line-through;
      opacity: 0.6;
    }
    .term.result {
      background: var(--accent);
      color: #fff;
    }
    .term.result .tl {
      color: #fff;
      opacity: 0.85;
    }
    .tl {
      font-size: 9.5px;
      color: var(--secondary-text-color);
      max-width: 120px;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }
    .tv {
      font-variant-numeric: tabular-nums;
      font-weight: 600;
    }
    .badge {
      font-size: 11px;
      padding: 4px 7px;
      border-radius: 6px;
      background: color-mix(in srgb, var(--secondary-text-color) 10%, transparent);
    }
    .badge.ok {
      background: color-mix(in srgb, #16a34a 12%, transparent);
    }
    .badge.warn {
      background: color-mix(in srgb, #d97706 14%, transparent);
    }
    .switch {
      display: grid;
      grid-template-columns: 1fr 1fr;
      border-radius: 8px;
      overflow: hidden;
      border: 1px solid var(--divider-color, #e5e7eb);
    }
    .pos {
      text-align: center;
      padding: 4px 0;
      color: var(--secondary-text-color);
    }
    .pos.on {
      background: ${css([NEUTRAL] as unknown as TemplateStringsArray)};
      color: #fff;
      font-weight: 600;
    }
    .pos.on.ppe2 {
      background: ${css([PPE2_COLOR] as unknown as TemplateStringsArray)};
    }
    .rule {
      display: flex;
      flex-direction: column;
      gap: 2px;
      padding: 4px 6px;
      border-radius: 6px;
      background: color-mix(in srgb, var(--accent) 8%, transparent);
    }
    .rule .ok {
      color: #16a34a;
    }
    .legend {
      display: flex;
      flex-wrap: wrap;
      gap: 6px 16px;
      margin-top: 10px;
      color: var(--secondary-text-color);
      font-size: 11px;
    }
    .legend span {
      display: inline-flex;
      align-items: center;
      gap: 6px;
    }
    .ln {
      display: inline-block;
      width: 26px;
      border-top: 2px dashed ${css([NEUTRAL] as unknown as TemplateStringsArray)};
      opacity: 0.5;
    }
    .ln.active {
      border-top: 3px dashed ${css([PPE1_COLOR] as unknown as TemplateStringsArray)};
      opacity: 1;
    }
    .ln.derived {
      border-top: 2px dotted ${css([COMPUTED] as unknown as TemplateStringsArray)};
      opacity: 1;
    }
    .box {
      display: inline-block;
      width: 14px;
      height: 10px;
      border: 1px solid var(--divider-color, #cbd5e1);
      border-left: 3px solid ${css([NEUTRAL] as unknown as TemplateStringsArray)};
      border-radius: 3px;
    }
    .box.computed {
      border-style: dashed;
      border-left: 3px solid ${css([COMPUTED] as unknown as TemplateStringsArray)};
    }
  `;
}

