const s = await hass.callWS({type: 'powerpilot/series', start: new Date(now.getTime() - 3*3600e3).toISOString(), end: new Date(now.getTime() + 1*3600e3).toISOString()});
const flow = await hass.callWS({type: 'powerpilot/flow'});
const plan = await hass.callWS({type: 'powerpilot/plan'});
const last = s.hours.filter(h => h.is_past && !h.partial).pop();
const st = (id) => { const x = hass.states[id]; return x ? {entity_id: id, name: x.attributes.friendly_name || id, value: x.state, unit: x.attributes.unit_of_measurement || null} : null; };
const ids = ['sensor.gx_device_consumption_power_l1','sensor.ess_multiplus_ii_output_power_l1','sensor.victron_grid_power','sensor.tongou_m3_power','sensor.garage_server_socket_power','sensor.victron_battery_soc','sensor.victron_battery_kwh_in','sensor.victron_battery_kwh_out','binary_sensor.kotek_charger','sensor.kotek_energy_added','sensor.salon_klimka_daily_energy','sensor.bathroom_boiler_socket_energy','sensor.tongou_m3_energy','sensor.garage_server_socket_energy','sensor.bedroom_wardrobe_socket_energy','sensor.ess_multiplus_ii_energy_from_ac_in_1_to_ac_out','sensor.ess_multiplus_ii_energy_from_ac_in_1_to_inverter','sensor.kotek_energy_total'];
const live = Object.fromEntries(ids.map(i => [i, st(i)]));
({last: {start: last.start, cons: last.consumption_real, dev: last.devices_real, grid: last.grid_buy_kwh, chg: last.battery_charge_kwh, dis: last.battery_discharge_kwh, ev: last.ev_charge_kwh, ppe2: last.ppe2_import_kwh, sa: last.supply_actual}, live, billing: plan.billing.map(b => ({ppe: b.period.ppe, binds: b.cap_binds, avg: b.average_kwh, limit: b.period.limit_kwh, terms: b.period.terms_name})), sup: flow.supply, batt: flow.battery.delivered_cost, evsoc: flow.ev.soc})

